<?php declare(strict_types=1);
$bankLedgerText??=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\BankLedgerMessages::text($source,[],$values);
if(!$selectedAccount||!$finance->canWrite())return;
$accountSetting=$finance->accountSettings($selectedAccount['id']);
$accountPosting=in_array($_POST['action']??null,\Kulturhus\Verein\Web\AccountSettingsForm::ACTIONS,true);
$accountEditingPosted=$accountPosting&&($_POST['action']??null)!=='finance-account-delete';
$accountDefaults=array_replace($accountSetting,['name'=>$selectedAccount['name'],'kind'=>$selectedAccount['kind'],'opening'=>\Kulturhus\Verein\Finance::decimal((int)$selectedAccount['opening_cents']),'opened_on'=>$selectedAccount['opened_on']]);
$accountDraft=$accountDefaults;if($accountEditingPosted)foreach(['version','name','kind','opening','opened_on','active','tax_account','fints_read','fints_write']as$accountField)$accountDraft[$accountField]=is_string($_POST[$accountField]??null)?$_POST[$accountField]:'';
elseif($accountPosting)$accountDraft['version']=is_string($_POST['version']??null)?$_POST['version']:'';
$accountUnsupported=$accountPosting?\Kulturhus\Verein\Web\AccountSettingsForm::unsupported($_POST):[];
if($accountPosting){foreach(\Kulturhus\Verein\Web\AccountSettingsForm::required($_POST)as$accountField)if(!array_key_exists($accountField,$_POST))$accountUnsupported[$accountField]=['missing'=>true];if(($_POST['account']??null)!==$selectedAccount['id'])$accountUnsupported['account']=$_POST['account']??['missing'=>true];if(!is_string($_POST['version']??null)||!preg_match('/\A(?:0|[1-9][0-9]{0,8})\z/D',$_POST['version']))$accountUnsupported['version']=$_POST['version']??['missing'=>true];}
if(($accountSettingsRefreshed??false)&&!$accountUnsupported)$accountDraft['version']=(string)$accountSetting['version'];
$accountUse=$finance->accountDeletionInfo($selectedAccount['id']);$accountUnused=$accountUse['blockers']===[];
$isBank=$selectedAccount['kind']==='offline';$accountTaxChoices=[];foreach($finance->taxAccounts()as$code=>$taxAccount)if($taxAccount['active']&&$taxAccount['category']==='current'&&!preg_match('/AM|AV/',$taxAccount['function']??''))$accountTaxChoices[(string)$code]=$taxAccount;
$accountUnknownOption=static function(string$value,array$allowed)use($bankLedgerText):string{if(in_array($value,$allowed,true))return'';return'<option value="'.e($value).'" selected>'.e($bankLedgerText('Ursprüngliche Auswahl nicht verfügbar: {value}',['value'=>$value])).'</option>';};
?>
