<form method="post" data-account-settings data-opening-kind="<?= e($selectedAccount['kind']) ?>"><fieldset class="account-mutation-controls" <?= $accountUnsupported?'disabled':'' ?>><legend class="sr-only"><?= e($bankLedgerText('Kontoeinstellungen bearbeiten')) ?></legend>
