  <label><?= e($bankLedgerText('Bestand ab')) ?><input class="form-control" name="opened_on" placeholder="YYYY-MM-DD" type="<?= \Kulturhus\Verein\Web\AccountSettingsForm::dateInputType(input($accountDraft,'opened_on')) ?>" required max="<?= date('Y-m-d') ?>" value="<?= e(input($accountDraft,'opened_on')) ?>"></label>
 </div><?php else: ?><p><?= e($bankLedgerText($isBank?'Bankkonto':'Handkasse')) ?> · <?= e($bankLedgerText('Anfangssaldo {amount} ab {date}',['amount'=>euro((int)$selectedAccount['opening_cents']),'date'=>dateDe($selectedAccount['opened_on'])])) ?>.</p><p><?= e($bankLedgerText('Kontoart und Anfangssaldo sind geschützt:')) ?> <?= e(implode('; ',array_map($bankLedgerText,$accountUse['blockers']))) ?>.</p><?php endif ?>
