  <label><?= e($bankLedgerText('Buchhaltungskonto (SKR42)')) ?><select class="form-control" name="tax_account" data-searchable-select><option value=""><?= e($bankLedgerText('Noch nicht zugeordnet')) ?></option><?= $accountUnknownOption(input($accountDraft,'tax_account'),array_merge([''],array_map('strval',array_keys($accountTaxChoices)))) ?><?php foreach($accountTaxChoices as $code=>$taxAccount): ?><option value="<?= e((string)$code) ?>" <?= input($accountDraft,'tax_account')===(string)$code?'selected':'' ?>><?= e($code.' · '.$taxAccount['name']) ?></option><?php endforeach ?></select></label>
